"""Translations of the NetBoxSelf Audit pages, reports and e-mails (en / sk / cs / de).

The language is chosen on the Watched fields page. Missing translations fall back to English.
"""

from __future__ import annotations

LANGUAGES = (
    ("en", "English"),
    ("sk", "Slovenčina"),
    ("cs", "Čeština"),
    ("de", "Deutsch"),
)
DEFAULT_LANGUAGE = "en"


def language_of(settings) -> str:
    lang = getattr(settings, "language", None) or DEFAULT_LANGUAGE
    return lang if lang in dict(LANGUAGES) else DEFAULT_LANGUAGE


def tr(key: str, lang: str = DEFAULT_LANGUAGE, **values) -> str:
    entry = MESSAGES.get(key)
    if entry is None:
        text = key
    else:
        text = entry.get(lang) or entry["en"]
    return text.format(**values) if values else text


